function createStandingsHeaders(e){for(const t of e){const e=document.createElement("th");e.textContent=t;document.getElementById("standings-header-row").appendChild(e)}}function createTeamRow(e,t,n){const o=document.createElement("tr"),a=document.createElement("th");a.scope="row",a.textContent=e,o.appendChild(a);for(const e of n){const n=document.createElement("td");n.textContent=t[e],o.appendChild(n)}return o}document.addEventListener("DOMContentLoaded",(async()=>{const e=await fetch("/api/standings-headers/");if(!e.ok)throw new Error("Network response was not ok");const t=await e.json();createStandingsHeaders(t);const n=await fetch("/api/standings-data/");if(!n.ok)throw new Error("Network response was not ok");const o=await n.json(),a=document.getElementById("standings-container");for(const[e,n]of o.entries()){const o=createTeamRow(e+1,n,t);a.appendChild(o)}document.getElementById("loading-div")?.remove()}));